'use strict';
let campEvent4=null;
const CampUI4={
 labels:{active:'Буткемп идёт',online:'Онлайн-подготовка',completed:'Программа завершена',cancelled:'Отменён менеджером',interrupted:'Прерван: изменились условия'},
 events(){return S.events.filter(e=>!e.done&&e.day>=S.day||Camp4.plans()[Camp4.key(e.id)]).sort((a,b)=>a.day-b.day||a.id-b.id);},
 selected(){const events=this.events();return events.find(e=>e.id===campEvent4)||events.find(e=>Camp4.confirmed(e,S.club)&&e.day-S.day>=7&&e.day-S.day<=14)||events.find(e=>!e.done&&Camp4.confirmed(e,S.club))||events[0];},
 view(){
  const e=this.selected(),A=Arena33C;if(!e)return head('ПОДГОТОВКА / V4.0','Буткемп','Новые программы появятся вместе с календарём турниров.');
  const b=Camp4.plans()[Camp4.key(e.id)],gap=e.day-S.day,ps=roster(),stats=Fans4.support(my());
  const status=b?this.labels[b.status]:Camp4.confirmed(e,S.club)?gap>=7&&gap<=14?'Окно бронирования открыто':gap<7?'До старта меньше семи дней':'Выбор откроется за 14 дней':'Участие пока не подтверждено';
  return '<div class="v4-camp">'+A.ribbon('PRE-SEASON / BOOTCAMP OPERATIONS','V4.0')+'<section class="panel v4-camp-hero"><div><span class="eyebrow">'+esc(status)+'</span><h1>Собрать пятёрку. Настроить форму.</h1><p>Семь календарных дней совместной подготовки к конкретному турниру. Каждый день работает на форму и восстановление команды.</p><label>Турнир <select aria-label="Турнир для буткемпа" onchange="campEvent4=+this.value;render()">'+this.events().map(event=>'<option value="'+event.id+'" '+(event.id===e.id?'selected':'')+'>'+esc(event.name)+' · '+date(event.day)+'</option>').join('')+'</select></label><div class="v4-event-meta"><span>'+date(e.day)+'</span><strong>'+Math.max(0,gap)+' дн. до старта</strong><span>'+esc(Camp4.confirmed(e,S.club)?'Участие подтверждено':'Нужен инвайт или выход из квалификации')+'</span></div></div><div class="v4-campus-art" aria-hidden="true">'+icon21('base')+'<b>TRAIN / RECOVER / COMPETE</b><div>'+Array.from({length:7},(_,i)=>'<i class="'+(b&&i<Object.keys(b.days).length?'done':'')+'">'+(i+1)+'</i>').join('')+'</div></div></section>'+
  '<div class="actions v4-camp-calendar">'+btn('Следующий день','advance()',true,!!S.active||!!S.practice13||busy13)+btn('Продолжить календарь','skip()',false,!!S.active||!!S.practice13||busy13)+'</div><div class="c-readiness v4-camp-metrics">'+A.metric('Бюджет',cash(S.budget),'Разовая оплата программы')+A.metric('Форма пятёрки',A.number(avg(ps.map(p=>p.form))),'Предел формы 95')+A.metric('Энергия',A.number(avg(ps.map(p=>100-p.fatigue)))+'%','Восстановление снижает усталость')+A.metric('Поддержка трибун','+'+A.number(stats.bonus),'Мораль · '+Math.round(stats.fans).toLocaleString('ru-RU')+' болельщиков')+'</div>'+
  (b?this.progress(e,b):'')+'<div class="v4-tier-grid">'+Object.entries(V4_CONFIG.camp.tiers).map(([key,tier])=>this.tier(e,key,tier,b)).join('')+'</div><section class="panel"><h2>Пятёрка перед выездом</h2><div class="v4-roster">'+ps.map(p=>'<article>'+portrait20(p)+'<div><b>'+esc(p.name)+'</b><small>'+ROLES[p.role]+'</small></div><span>Форма '+A.number(p.form)+'</span><span>Энергия '+A.number(100-p.fatigue)+'%</span></article>').join('')+'</div></section>'+this.history()+'<details class="panel v4-camp-rules"><summary>Регламент подготовки и возвраты</summary><ul><li>Выбор за 7–14 дней до старта при подтверждённом участии. Одна программа на команду и турнир. Оплата сразу, бонусы — только за прошедшие дни.</li><li>Онлайн-подготовка бесплатна и сохраняет обычные тренировки без бонусов буткемпа. Ничего не выбирать тоже означает обычную подготовку.</li><li>Бонус формы складывается из ежедневной прибавки и усиления положительного прироста обычной тренировки. Потолок 95 сохраняется; превышение обычного календарного потолка ограничено пятью пунктами. OVR и SIN не повышаются напрямую.</li><li>Пропуск занятий убирает прибавку формы буткемпа за этот день, но восстановление остаётся. Одновременный турнир или КВ прерывает программу.</li><li>Добровольная отмена: 80% стоимости оставшихся дней. Прерывание из-за начала соревнований, отмены или сдвига турнира раньше конца программы: 100% стоимости неиспользованных дней. Повторное бронирование на тот же турнир невозможно.</li><li>Перенос турнира на более позднюю дату не продлевает уже оплаченную семидневную программу. Соперники выбирают и оплачивают подготовку по тем же правилам из своего бюджета.</li></ul></details></div>';
 },
 history(){const rows=Object.values(Camp4.plans()).filter(b=>b.team===S.club).sort((a,b)=>b.start-a.start).slice(0,8);return '<section class="panel"><h2>История подготовки</h2>'+(rows.length?'<div class="table-wrap"><table><thead><tr><th>Турнир</th><th>Программа</th><th>Статус</th><th>Дней</th><th>Бонус формы</th><th>Возврат</th></tr></thead><tbody>'+rows.map(b=>{const days=Camp4.results(b);return '<tr><td>'+esc(S.events.find(e=>e.id===b.event)?.name||'Турнир')+'</td><td>'+V4_CONFIG.camp.tiers[b.tier].label+'</td><td>'+this.labels[b.status]+'</td><td>'+days.length+'/7</td><td>'+Arena33C.signed(days.reduce((n,d)=>n+d.form,0))+'</td><td>'+cash(b.refund)+'</td></tr>';}).join('')+'</tbody></table></div>':'<p>Подготовка ещё не выбрана. Здесь появятся реальные результаты программ.</p>')+'</section>';},
 tier(e,key,tier,b){
  const A=Arena33C,reason=Camp4.reason(e,S.club,key),selected=b?.tier===key;
  return '<article class="panel v4-tier '+key+' '+(selected?'selected':'')+'"><span class="eyebrow">'+tier.tag+'</span><div class="v4-tier-icon" aria-hidden="true">'+icon21(key==='online'?'database':key==='elite'?'team':'base')+'</div><h2>'+tier.label+'</h2><p>'+tier.description+'</p><strong class="v4-price">'+(tier.cost?cash(tier.cost):'Бесплатно')+'</strong><small>7 дней · вся основная пятёрка</small><ul><li>Форма: '+(tier.form?'+'+A.number(tier.form)+' в день':'обычная динамика')+'</li><li>Положительный прирост формы: '+(tier.growth?'+'+Math.round(tier.growth*100)+'%':'без усиления')+'</li><li>Доп. восстановление: '+(tier.recovery?'−'+A.number(tier.recovery)+' усталости в день':'нет')+'</li></ul><div class="v4-total"><span>За полную неделю до ограничений</span><b>'+A.signed(tier.form*7)+' формы · −'+A.number(tier.recovery*7)+' усталости</b><small>На одного игрока; усиление обычного прироста формы считается дополнительно.</small></div>'+btn(selected?'Выбрано':key==='online'?'Готовиться онлайн':'Выбрать программу',"askCamp4("+e.id+",'"+key+"')",key==='elite',!!reason)+'<p class="sub">'+esc(selected?this.labels[b.status]:reason||'Средства спишутся после подтверждения.')+'</p></article>';
 },
 progress(e,b){
  if(b.tier==='online')return '<section class="panel"><h2>Онлайн-подготовка подтверждена</h2><p>Обычные тренировки по плану клуба. Бонусов и расходов буткемпа нет. '+date(b.start)+' — '+date(b.end)+'.</p></section>';
  const A=Arena33C,days=Camp4.results(b),form=days.reduce((n,d)=>n+d.form,0),recovery=days.reduce((n,d)=>n+d.recovery,0);
  return '<section class="panel v4-camp-progress"><div class="section-head"><div><span class="eyebrow">'+this.labels[b.status]+'</span><h2>'+V4_CONFIG.camp.tiers[b.tier].label+'</h2></div><strong>'+Object.keys(b.days).length+' / 7 дней</strong></div><p>'+date(b.start)+' — '+date(b.end)+' · оплачено '+cash(b.cost)+(b.refund?' · возвращено '+cash(b.refund):'')+'</p>'+(e.day!==b.eventDay?'<div class="notice">Дата турнира изменилась: '+date(b.eventDay)+' → '+date(e.day)+'. Даты уже оплаченного буткемпа не растягиваются.</div>':'')+'<div class="v4-day-track">'+Array.from({length:7},(_,i)=>{const d=days.find(d=>d.day===b.start+i+1);return '<div class="'+(d?'done':'')+'"><small>ДЕНЬ '+(i+1)+'</small><b>'+date(b.start+i+1)+'</b><span>'+(d?A.signed(d.form)+' формы':(b.status==='active'?'Впереди':'Не использован'))+'</span><span>'+(d?'−'+A.number(d.recovery)+' усталости':'Без начислений')+'</span></div>';}).join('')+'</div><p>Фактические бонусы в среднем на игрока за прошедшие дни: <b>'+A.signed(form)+' формы</b> и <b>−'+A.number(recovery)+' усталости</b>. Это прибавки буткемпа, а не вся дневная динамика.</p>'+(b.status==='active'?btn('Отменить оставшиеся дни','askCancelCamp4('+e.id+')'):'')+'</section>';
 }
};
function askCamp4(event,tier){const e=S.events.find(e=>e.id===event),reason=Camp4.reason(e,S.club,tier);if(reason){toast(reason);return;}const cfg=V4_CONFIG.camp.tiers[tier];openModal('<span class="eyebrow">ПОДГОТОВКА К ТУРНИРУ</span><h2>'+cfg.label+'</h2><p>'+esc(e.name)+' · семь дней с '+date(S.day)+'.</p><p>Разовая оплата: <b>'+cash(cfg.cost)+'</b>. Бонусы начисляются ежедневно. Выбор программы на этот турнир окончательный; условия отмены указаны в разделе буткемпа.</p><div class="actions">'+btn('Назад','closeModal()')+btn(cfg.cost?'Оплатить '+cash(cfg.cost):'Подтвердить онлайн',"confirmCamp4("+event+",'"+tier+"')",true)+'</div>');}
function confirmCamp4(event,tier){const r=Camp4.book(event,tier);if(!r.ok){toast(r.reason);return;}campEvent4=event;closeModal();save();go('bootcamp');}
function askCancelCamp4(event){const b=Camp4.plans()[Camp4.key(event)];if(!b||b.status!=='active')return;const refund=Math.floor(b.cost*(7-Object.keys(b.days).length)/7*.8);openModal('<h2>Отменить оставшиеся дни?</h2><p>Возврат: '+cash(refund)+'. Уже полученные бонусы сохраняются. Повторный буткемп на этот турнир недоступен.</p><div class="actions">'+btn('Продолжить буткемп','closeModal()')+btn('Отменить программу','cancelCamp4('+event+')',true)+'</div>');}
function cancelCamp4(event){const b=Camp4.plans()[Camp4.key(event)];if(b&&Camp4.close(b,'cancelled',true)){closeModal();save();render();}}
PAGES.splice(PAGES.findIndex(p=>p[0]==='tactics'),0,['bootcamp','⌂','Буткемп']);
const renderBeforeV4=render;
render=function(...args){const r=renderBeforeV4(...args);if(!S)return r;
 const nav=$('nav');if(!nav.innerHTML.includes("go('bootcamp')"))nav.innerHTML+='<button class="'+(page==='bootcamp'?'active':'')+'" onclick="go(\'bootcamp\')">'+icon21('base')+'<span>Буткемп</span></button>';
 $('mobileNav33c').innerHTML=[['home','Главная','◈'],['squad','Команда','♙'],['match','Матч','▷'],['bootcamp','Буткемп','⌂'],['menu21','Ещё','☰']].map(([key,label,icon])=>'<button aria-current="'+(page===key?'page':'false')+'" onclick="go(\''+key+'\')"><span aria-hidden="true">'+icon+'</span>'+label+'</button>').join('');
 if(page==='bootcamp'&&!busy13&&!S.practice13)$('app').innerHTML=CampUI4.view();
 $('broadcastStatus33c').innerHTML=$('broadcastStatus33c').innerHTML.replace('3.3 C / ARENA','V4.0 / ARENA');
 return r;
};
const homeBeforeV4=home;
home=function(...args){const html=homeBeforeV4(...args),e=CampUI4.events().find(e=>Camp4.confirmed(e,S.club)&&e.day-S.day>=7&&e.day-S.day<=14);return html+(e?'<section class="panel v4-home-camp"><div><span class="eyebrow">ОКНО ПОДГОТОВКИ ОТКРЫТО</span><h2>'+esc(e.name)+'</h2><p>'+((Camp4.plans()[Camp4.key(e.id)])?'Программа выбрана. Следите за дневными результатами.':'До старта '+(e.day-S.day)+' дней. Выберите буткемп или онлайн-подготовку.')+'</p></div>'+btn('Открыть буткемп',"campEvent4="+e.id+";go('bootcamp')",true)+'</section>':'');};
const teamCardBeforeV4=amTeamCard;
amTeamCard=function(team){const info=Fans4.support(team);return teamCardBeforeV4(team)+'<section class="panel v4-fan-support"><div>'+icon21('team')+'<h3>Поддержка болельщиков</h3></div><strong>'+Math.round(info.fans).toLocaleString('ru-RU')+'</strong><p>До <b>+'+Arena33C.number(info.bonus)+' к морали</b> игроков клуба. Это ограниченный вклад в текущую мораль, а не ежедневная прибавка. При росте или снижении аудитории поддержка пересчитывается; результат матча не гарантируется.</p></section>';};
const qualifiersViewBeforeV4=qualifiersView;
qualifiersView=function(){let html=qualifiersViewBeforeV4(),e=qualifierParent();if(e?.qualification?.majorVersion!==4)return html;const q=e.qualification;
 html=html.replace(/Индекс ([0-9.]+)/g,(text,value)=>'Место '+(q.rows?.find(r=>r.index.toFixed(4)===value)?.rank??'—')).replaceAll('В региональном турнире нужно занять место не ниже квоты.','В международном отборе нужно занять место не ниже квоты.').replace('Объявление шести приглашений','Объявление '+Majors4.inviteCount(e)+' приглашений').replaceAll('Ваш путь — региональная квалификация','Ваш путь — международная квалификация').replaceAll('Ваш индекс','Ваш показатель').replaceAll('Региональный турнир','Международный отбор').replaceAll('GLOBAL','Все регионы');
 return '<section class="panel v4-major-rules"><span class="eyebrow">ПРИОРИТЕТ СЕЗОННОГО РЕЙТИНГА</span><h2>'+Majors4.inviteCount(e)+' прямых приглашений · '+(format6(e).n-Majors4.inviteCount(e))+' мест через отбор</h2><p>Крупный турнир: '+esc(e.name)+'. Приглашения по той же таблице, что в рейтинге сезона: очки → Elo → ID клуба. Региональные лимиты не вытесняют топ-15. При накладке дат турнир переносится, чтобы сохранить топ-команды; после фиксации рейтинга список не пересчитывается.</p><p>'+((q.snapshotDay!=null)?'Снимок рейтинга: '+date(q.snapshotDay):'Объявление: '+date(e.day-QUALIFIERS.snapshotLead))+'. Международная квалификация принимает лучшие '+(format6(e).n-Majors4.inviteCount(e)>1?16:8)+' свободных клубов, оставшихся без инвайта.</p></section>'+html;
};
const rankingBeforeV4=rankingView13;
rankingView13=function(){return rankingBeforeV4().replace(/Новые BLAST, PGL, ESL и DreamLeague:[\s\S]*?сохраняют свои правила\./,'V4.0: новые крупные турниры приглашают топ-15 рейтинга сезона напрямую (16 приглашений для поля на 24). Остальные места — международная квалификация. Ранее сыгранные отборы и активные турниры сохраняют составы.');};
const alertsBeforeV4=alerts33C;
alerts33C=function(){const rows=alertsBeforeV4(),e=Camp4.choiceEvent();if(e)rows.unshift({text:'Открыт выбор подготовки: '+e.name+' · '+(e.day-S.day)+' дней до старта.',action:'campEvent4='+e.id+";go('bootcamp')",label:'Выбрать буткемп',kind:'info'});return rows;};
const profileBeforeV4=playerView20;
playerView20=function(...args){const html=profileBeforeV4(...args),p=S.players[selectedPlayer20];if(!p||p.team===null||p.retired)return html;const info=Fans4.support(S.teams[p.team]),applied=p.v4FanSupport?.team===p.team?p.v4FanSupport.applied:0;return html+'<section class="panel v4-fan-support"><h3>Поддержка клуба · '+esc(S.teams[p.team].name)+'</h3><p>'+Math.round(info.fans).toLocaleString('ru-RU')+' болельщиков · вклад в показанную мораль: <b>+'+Arena33C.number(applied)+'</b>. Потенциал поддержки сейчас: +'+Arena33C.number(info.bonus)+'. Пересчёт при смене дня и перед новой картой.</p></section>';};

const qualifierCardBeforeV4=qualifierCard;
qualifierCard=function(parent,...args){let html=qualifierCardBeforeV4(parent,...args);if(parent.qualification?.majorVersion!==4)return html;return html.replaceAll('Ваш путь — региональная квалификация','Ваш путь — международная квалификация').replace(/Ваш индекс [0-9.]+\./,'Ваше место в снимке рейтинга: '+(parent.qualification.rows?.find(r=>r.team===S.club)?.rank??'—')+'.');};
